SELECT set_config('request.jwt.claim.sub','f49d6153-1835-4455-81f3-2918d5d3484e',false);
BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile group''s HR analytics team calculates that employee turnover costs an average of $850 per departing worker (recruitment + training + productivity ramp-up loss), and current annual turnover is 42% across a 3,000-person workforce. A proposed retention program costing $380,000/year is projected to reduce turnover to 31%. Does this program pay for itself on pure turnover-cost savings alone?', '["Current turnover cost = 3,000×0.42×$850=$1,071,000. Projected turnover cost = 3,000×0.31×$850=$790,500. Savings = $1,071,000−$790,500=$280,500 — this FALLS SHORT of the $380,000 program cost by $99,500, meaning the program does NOT pay for itself on pure turnover-cost savings alone, though other benefits (morale, productivity, quality — connecting to the earlier employee-satisfaction-leading-indicator discussion) might still justify it","Savings = $380,000 exactly, meaning the program breaks exactly even, neither a net cost nor a net saving on pure turnover-cost grounds alone","Savings = $1,071,000, incorrectly treating the ENTIRE current turnover cost as if it would be completely eliminated rather than only reduced from 42% to 31%","The program clearly and comfortably pays for itself with over $500,000 in net savings, substantially understating the actual calculation by using an incorrect turnover-cost baseline"]'::jsonb, 'Current turnover cost = 3,000×0.42×$850=$1,071,000. Projected turnover cost = 3,000×0.31×$850=$790,500. Savings = $1,071,000−$790,500=$280,500 — this FALLS SHORT of the $380,000 program cost by $99,500, meaning the program does NOT pay for itself on pure turnover-cost savings alone, though other benefits (morale, productivity, quality — connecting to the earlier employee-satisfaction-leading-indicator discussion) might still justify it', 'Current annual turnover cost = 3,000 employees × 42% × $850 = $1,071,000. Projected (post-program) turnover cost = 3,000 × 31% × $850 = $790,500. Direct turnover-cost savings = $1,071,000−$790,500 = $280,500 — this falls short of the $380,000 program cost by $99,500, meaning the program does NOT pay for itself using PURE turnover-cost savings alone — this connects to the earlier employee-satisfaction-as-leading-indicator discussion: a complete business case for this investment would need to ALSO account for the harder-to-quantify but real additional benefits (morale, quality, engagement with improvement initiatives) beyond just the direct, easily-measured turnover-cost savings, illustrating why HR investment decisions often require weighing quantifiable AND qualitative benefits together rather than relying on one narrow cost-savings calculation alone.', 3, '{"retention-program-ROI-calculation"}'::text[]),
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile group''s board reviews a ''balanced scorecard'' (tracking Financial, Customer, Internal Process, and Learning & Growth metrics together, rather than financial metrics alone) for quarterly performance review. A director questions why ''Learning & Growth'' metrics (e.g., employee training hours, skill certification rates) deserve board-level attention alongside financial results. What is the strategic logic connecting Learning & Growth metrics to FUTURE financial performance?', '["Learning & Growth metrics have no genuine connection to future financial performance and are included in balanced scorecards purely as an arbitrary, non-substantive category with zero strategic logic behind their inclusion","The balanced scorecard''s core logic is that Learning & Growth (workforce capability, skill development) drives future Internal Process improvement (better, more capable execution), which drives future Customer outcomes (better quality/service), which ultimately drives future Financial results — Learning & Growth metrics are essentially LEADING indicators of financial performance still to come, similar in principle to the earlier employee-satisfaction-as-leading-indicator discussion, meaning a board focused only on CURRENT financial results is missing visibility into the capability investments that will drive NEXT period''s results","Financial metrics are always sufficient on their own to fully predict all future business performance, making any non-financial metric category (including Learning & Growth) strategically redundant for board-level review purposes","Learning & Growth metrics should only ever be reviewed by the HR department in isolation, with zero relevance to board-level strategic oversight or connection to the company''s overall financial trajectory"]'::jsonb, 'The balanced scorecard''s core logic is that Learning & Growth (workforce capability, skill development) drives future Internal Process improvement (better, more capable execution), which drives future Customer outcomes (better quality/service), which ultimately drives future Financial results — Learning & Growth metrics are essentially LEADING indicators of financial performance still to come, similar in principle to the earlier employee-satisfaction-as-leading-indicator discussion, meaning a board focused only on CURRENT financial results is missing visibility into the capability investments that will drive NEXT period''s results', 'This connects the earlier employee-satisfaction-as-leading-indicator principle to the broader, more formal Balanced Scorecard strategic management framework — the scorecard''s core causal logic runs: Learning & Growth investment (workforce capability) → improved Internal Process execution → better Customer outcomes → eventual Financial results — since financial metrics are inherently LAGGING (reflecting what already happened), and Learning & Growth metrics are LEADING (predicting future capability to execute and deliver value), board-level attention to Learning & Growth isn''t a distraction from financial oversight but rather genuine early visibility into the capability investments that will drive results in FUTURE periods, exactly the same underlying leading-vs-lagging-indicator logic established earlier for employee satisfaction specifically, now generalized to this broader strategic framework.', 3, '{"balanced-scorecard-leading-indicators"}'::text[]),
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile group''s strategy team debates entering a NEW geographic market via GREENFIELD investment (building an entirely new factory from scratch) versus ACQUISITION (buying an existing local factory) versus JOINT VENTURE (partnering with a local company, as discussed earlier). Beyond the earlier JV-specific tradeoffs, what SPEED-vs-CONTROL tradeoff distinguishes greenfield from acquisition specifically?', '["Greenfield and acquisition offer mathematically identical speed-to-market and control characteristics, making the choice between them purely a matter of preference with zero underlying strategic tradeoff","Greenfield investment offers MAXIMUM control (building exactly the facility/culture/systems wanted from scratch, with no inherited legacy issues) but takes SIGNIFICANTLY LONGER to reach operational capacity (construction, hiring, training, ramp-up all starting from zero) — acquisition offers FASTER market entry (an already-operational facility with existing workforce/customer relationships) but requires accepting whatever legacy systems, culture, equipment condition, and potential hidden liabilities (echoing the earlier M&A-hidden-compliance-cost discussion) come with the acquired business, a genuine speed-vs-control/inherited-risk tradeoff between these two market-entry approaches","Acquisition always takes LONGER to reach operational capacity than greenfield investment, the reverse of the actual typical speed relationship between these two market-entry strategies","Market entry strategy choice (greenfield vs. acquisition vs. joint venture) has no relationship to speed-to-market or degree of operational control, making this entire strategic comparison technically irrelevant to real international expansion decisions"]'::jsonb, 'Greenfield investment offers MAXIMUM control (building exactly the facility/culture/systems wanted from scratch, with no inherited legacy issues) but takes SIGNIFICANTLY LONGER to reach operational capacity (construction, hiring, training, ramp-up all starting from zero) — acquisition offers FASTER market entry (an already-operational facility with existing workforce/customer relationships) but requires accepting whatever legacy systems, culture, equipment condition, and potential hidden liabilities (echoing the earlier M&A-hidden-compliance-cost discussion) come with the acquired business, a genuine speed-vs-control/inherited-risk tradeoff between these two market-entry approaches', 'This completes the three-way market-entry strategy comparison (alongside the earlier joint-venture discussion) with the genuine greenfield-vs-acquisition tradeoff — greenfield offers the cleanest possible control (no inherited legacy systems, culture, or hidden liabilities, building exactly what''s wanted from the ground up) but requires starting completely from zero (construction, hiring, training, customer relationship-building), taking substantially longer to reach full operational capacity; acquisition offers immediate operational capability (existing workforce, facility, and often existing customer relationships) but requires accepting whatever legacy conditions, culture, and potential hidden risks (directly connecting to the earlier M&A-hidden-compliance-cost discussion) come bundled with the acquired business — together with the earlier-discussed joint-venture middle-ground option, this gives a complete three-way strategic framework for international market-entry mode selection.', 3, '{"greenfield-vs-acquisition-tradeoff"}'::text[]);
COMMIT;
